namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious traditional Italian pizza.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake for 10–12 minutes.", "Top with fresh basil and a drizzle of olive oil."]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water.", "Fry pancetta until crispy.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture quickly.", "Serve immediately with extra cheese."]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and spices.", "Add chicken and simmer 10 minutes."]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Description = "A quick stir-fried noodle dish with vegetables and peanuts.",
            Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Peanuts", "Pad Thai sauce", "Lime", "Green onions"],
            Steps = ["Soak rice noodles in warm water.", "Press and cube tofu, then pan-fry.", "Stir-fry vegetables until tender.", "Add drained noodles and sauce.", "Toss everything together.", "Serve with crushed peanuts and lime wedges."]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer.", "Warm tortillas in a dry pan.", "Fill tortillas with beef.", "Add lettuce, tomato, cheese, sour cream.", "Serve with salsa on the side."]
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk in eggs, sugar, and vanilla.", "Fold in flour gently.", "Pour into greased ramekins.", "Bake for 12–14 minutes until edges are set but center is soft."]
        },
        new()
        {
            Id = 7, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh and creamy avocado dip.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Salt", "Tomato"],
            Steps = ["Halve and pit avocados.", "Mash to desired consistency.", "Stir in lime juice, salt.", "Fold in diced onion, tomato, jalapeño, cilantro.", "Taste and adjust seasoning.", "Serve immediately with chips."]
        },
        new()
        {
            Id = 8, Title = "Miso Ramen", Category = "Asian",
            Description = "Hearty Japanese noodle soup with miso broth.",
            Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Soft-boiled egg", "Green onions", "Nori", "Corn"],
            Steps = ["Bring broth to a simmer.", "Whisk in miso paste and soy sauce.", "Cook ramen noodles separately.", "Place noodles in bowls, ladle broth over.", "Top with halved soft-boiled egg, corn, nori.", "Garnish with sliced green onions."]
        }
    ];

    private int _nextId = 9;

    public List<RecipeCategory> GetCategories() =>
    [
        new() { Name = "Italian", Description = "Pastas, pizzas, and Mediterranean flavors", Icon = "🍝" },
        new() { Name = "Indian", Description = "Rich curries and aromatic spices", Icon = "🍛" },
        new() { Name = "Asian", Description = "Stir-fries, noodles, and umami-packed dishes", Icon = "🍜" },
        new() { Name = "Mexican", Description = "Tacos, salsas, and bold flavors", Icon = "🌮" },
        new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" }
    ];

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

